mapper.select:
select distinct c.mid from (
    select f.follow_member_id as mid from ums_member_follow f where f.member_id = #{memberId}
    union
    select mate.member_id as mid from club_member mine
      join club_member mate on mate.club_id = mine.club_id and mate.status = 1 and mate.del_flag = 0
     where mine.member_id = #{memberId} and mine.status = 1 and mine.del_flag = 0
) c

where c.mid <> #{memberId} and ifnull(p.leaderboard_scope, 'IN') <> 'OUT'
order by c.mid
limit #{cap}
